"""Validate an operator-reviewed Native intersection backing corridor."""
from hashlib import sha256
import json
from math import hypot, isfinite
from pathlib import Path


def _point(value):
    if not isinstance(value, list) or len(value) != 2 or any(type(x) not in (int, float) or not isfinite(x) for x in value):
        raise ValueError('Native backing corridor needs finite XY points')
    return tuple(float(x) for x in value)


def _inside(point, polygon):
    x, y = point
    inside = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        x1, y1 = a; x2, y2 = b
        if (y1 > y) != (y2 > y) and x < (x2-x1)*(y-y1)/(y2-y1)+x1:
            inside = not inside
    return inside


def verify(world_map, path, ego_heading_xy):
    path = Path(path)
    raw = path.read_bytes()
    source = json.loads(raw)
    if (source.get('format') != 'worker-native-backing-corridor-v1' or
            source.get('verified_intersection') is not True or
            not source.get('reviewer') or not source.get('evidence_reference') or
            not source.get('other_vehicle_purpose')):
        raise ValueError('Reviewed Native backing corridor identity is absent')
    if source.get('map_name') != world_map.name or source.get('opendrive_sha256') != sha256(world_map.to_opendrive().encode()).hexdigest():
        raise ValueError('Native backing corridor map/OpenDRIVE differs')
    polygon = [_point(p) for p in source['intersection_polygon_xy']]
    if len(polygon) < 3:
        raise ValueError('Intersection polygon is incomplete')
    start, end, other = [_point(source[key]) for key in ('start_xy', 'end_xy', 'other_vehicle_xy')]
    if not all(_inside(point, polygon) for point in (start, end)):
        raise ValueError('Reverse path leaves reviewed intersection corridor')
    if not _inside(other, polygon):
        raise ValueError('Other traffic actor is outside reviewed intersection context')
    heading = _point(list(ego_heading_xy));norm=hypot(*heading)
    length=hypot(end[0]-start[0],end[1]-start[1])
    if norm < .5 or length < 5 or length > 25 or ((end[0]-start[0])*heading[0]+(end[1]-start[1])*heading[1])/norm > -4:
        raise ValueError('Selected corridor does not construct a bounded reverse route')
    for key in ('other_vehicle_road_id', 'other_vehicle_lane_id'):
        if type(source.get(key)) is not int:
            raise ValueError('Other vehicle needs a sourced Native road/lane identity')
    return {'format':'worker-native-backing-corridor-verification',
            'source_sha256':sha256(raw).hexdigest(),'map_name':world_map.name,
            'opendrive_sha256':source['opendrive_sha256'],
            'start_xy':start,'end_xy':end,'other_vehicle_xy':other,
            'other_vehicle_purpose':source['other_vehicle_purpose'],
            'other_vehicle_road_id':source['other_vehicle_road_id'],
            'other_vehicle_lane_id':source['other_vehicle_lane_id'],
            'reviewer':source['reviewer'],'evidence_reference':source['evidence_reference'],
            'physical_motion_claimed':False,'legal_safety_claimed':False}

"""Original 20 Hz ego, traffic and contact recorder for intersection backing."""
from hashlib import sha256
import json
from math import hypot, isfinite
from pathlib import Path


def _body(actor):
    transform=actor.get_transform();location=transform.location
    extent=actor.bounding_box.extent
    values=(location.x,location.y,extent.x,extent.y)
    if any(not isfinite(float(v)) for v in values) or min(extent.x,extent.y)<=0:
        raise ValueError('Native participant body readback is invalid')
    return {'x_m':float(location.x),'y_m':float(location.y),
            'body_radius_m':float(hypot(extent.x,extent.y))}


class BackingSourceRecorder:
    def __init__(self, directory, ego, participants, context):
        self.directory=Path(directory);self.ego=ego
        self.participants={str(actor.id):actor for actor in participants}
        if not self.participants or len(self.participants)!=len(participants) or str(ego.id) in self.participants:
            raise ValueError('Distinct Native traffic participants required')
        if set(self.participants)!=set(context.get('participants',{})):
            raise ValueError('Surrounding traffic context/actor identities differ')
        for actor_id,item in context['participants'].items():
            if item.get('kind') not in ('vehicle','pedestrian') or not item.get('position_motion_purpose_source') or not item.get('highway_use_source'):
                raise ValueError('Every participant needs sourced motion, purpose and highway use')
        self.directory.mkdir(parents=True,exist_ok=True)
        self.context=self.directory/'backing_context.json'
        self.context.write_text(json.dumps(context,indent=2)+'\n')
        self.motion=(self.directory/'backing_motion.jsonl').open('x')
        self.contacts_path=self.directory/'backing_contacts.jsonl'
        self.last=None;self.pending={};self.frames=[]

    def contact(self, frame, other_actor_id):
        actor_id=str(other_actor_id)
        if actor_id not in self.participants or type(frame) is not int:
            raise ValueError('Native contact has unknown actor or invalid frame')
        self.pending.setdefault(frame,set()).add(actor_id)

    def append(self, frame, time_s):
        if type(frame) is not int or type(time_s) not in (int,float) or not isfinite(time_s) or self.last is not None and (frame!=self.last[0]+1 or abs(time_s-self.last[1]-.05)>1e-4):
            raise ValueError('Native backing frame/time sequence differs from 20 Hz')
        heading=self.ego.get_transform().get_forward_vector();velocity=self.ego.get_velocity()
        if any(not isfinite(float(v)) for v in (heading.x,heading.y,velocity.x,velocity.y)):
            raise ValueError('Native backing heading/velocity is nonfinite')
        bodies={}
        for actor_id,actor in self.participants.items():
            body=_body(actor);speed=actor.get_velocity()
            body['speed_mps']=float(hypot(speed.x,speed.y));bodies[actor_id]=body
        row={'frame':frame,'time_s':time_s,'ego':_body(self.ego),
             'ego_heading_xy':[float(heading.x),float(heading.y)],
             'ego_velocity_xy':[float(velocity.x),float(velocity.y)],
             'participants':bodies}
        self.motion.write(json.dumps(row,allow_nan=False)+'\n')
        self.motion.flush();self.last=(frame,time_s);self.frames.append((frame,time_s))
        return row

    def close(self):
        if set(self.pending)-{frame for frame,_ in self.frames}:
            raise ValueError('Unjoined Native contact frame remains')
        self.motion.close()
        with self.contacts_path.open('x') as stream:
            for frame,time_s in self.frames:
                stream.write(json.dumps({'frame':frame,'time_s':time_s,
                    'contact_actor_ids':sorted(self.pending.get(frame,set()))})+'\n')
        return {'backing_motion.jsonl':sha256((self.directory/'backing_motion.jsonl').read_bytes()).hexdigest(),
                'backing_contacts.jsonl':sha256((self.directory/'backing_contacts.jsonl').read_bytes()).hexdigest(),
                'backing_context.json':sha256(self.context.read_bytes()).hexdigest()}

"""Four synchronized original RGB source streams for backing probes."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown backing source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior backing camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original backing camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Alley source encoder failed")


class BackingCameraCapture:
    def __init__(self, world, carla_module, ego, sinks, *, overview_height_delta_m=0):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named backing source sinks required")
        if overview_height_delta_m not in (0, 2):
            raise ValueError("Unsupported overview camera height change")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                if name == 'overview':
                    loc = (loc[0], loc[1], loc[2] + overview_height_delta_m)
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original backing camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original backing camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Alley source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original backing source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original backing camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

"""Original-frame backing and surrounding-user measurements for NRS 484B.113(1).

Reverse motion, separation, deceleration and contact are observations. They do
not decide reasonable safety or interference with other traffic.
"""

from hashlib import sha256
import json
from math import atan2, degrees, hypot, isfinite
from pathlib import Path


def _rows(path, label):
    path = Path(path)
    if not path.is_file() or not path.read_bytes():
        raise ValueError('Missing original source: ' + label)
    raw = path.read_bytes()
    try:
        return [json.loads(line) for line in raw.splitlines()], sha256(raw).hexdigest()
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid original source: ' + label) from error


def _body(item, label):
    try:
        values = tuple(float(item[key]) for key in ('x_m', 'y_m', 'body_radius_m'))
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError('Missing original body geometry: ' + label) from error
    if not all(isfinite(v) for v in values) or values[2] <= 0:
        raise ValueError('Invalid original body geometry: ' + label)
    return values


def _vector(item, label):
    if not isinstance(item, list) or len(item) != 2:
        raise ValueError('Missing original vector: ' + label)
    try:
        values = tuple(float(v) for v in item)
    except (TypeError, ValueError) as error:
        raise ValueError('Invalid original vector: ' + label) from error
    if not all(isfinite(v) for v in values):
        raise ValueError('Invalid original vector: ' + label)
    return values


def measure(motion_path, contact_path, context_path):
    motion, motion_sha = _rows(motion_path, 'backing_motion.jsonl')
    contacts, contact_sha = _rows(contact_path, 'backing_contacts.jsonl')
    context_path = Path(context_path)
    if not context_path.is_file() or not context_path.read_bytes():
        raise ValueError('Missing original source: backing_context.json')
    context_raw = context_path.read_bytes()
    try:
        context = json.loads(context_raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid original backing context') from error
    if len(motion) < 3 or len(contacts) != len(motion):
        raise ValueError('Original backing motion/contact history incomplete')
    participants = context.get('participants')
    if not isinstance(participants, dict) or not participants:
        raise ValueError('Surrounding traffic context required')
    for actor_id, item in participants.items():
        if not isinstance(actor_id, str) or not actor_id or not isinstance(item, dict) or (
                item.get('kind') not in ('vehicle', 'pedestrian') or
                not item.get('position_motion_purpose_source') or
                not item.get('highway_use_source')):
            raise ValueError('Each surrounding user needs independently cited context')
    observations = []
    prior = None
    speeds = {}
    prior_gaps = {}
    for row, contact in zip(motion, contacts):
        frame, time_s = row.get('frame'), row.get('time_s')
        if type(frame) is not int or type(time_s) not in (int, float) or not isfinite(time_s):
            raise ValueError('Original backing frame/time invalid')
        if prior is not None and (frame != prior[0] + 1 or abs(time_s - prior[1] - .05) > 1e-4):
            raise ValueError('Original backing frames are not joined at 20 Hz')
        prior = frame, time_s
        if (contact.get('frame'), contact.get('time_s')) != (frame, time_s):
            raise ValueError('Original contact/motion frame join failed')
        contact_ids = contact.get('contact_actor_ids')
        if not isinstance(contact_ids, list) or len(contact_ids) != len(set(contact_ids)) or (
                set(contact_ids) - set(participants)):
            raise ValueError('Original contact actor identities invalid')
        ego = _body(row.get('ego'), 'ego')
        heading = _vector(row.get('ego_heading_xy'), 'ego heading')
        velocity = _vector(row.get('ego_velocity_xy'), 'ego velocity')
        hnorm = hypot(*heading)
        if hnorm < 1e-6:
            raise ValueError('Original backing heading degenerate')
        longitudinal = (heading[0] * velocity[0] + heading[1] * velocity[1]) / hnorm
        bodies = row.get('participants')
        if not isinstance(bodies, dict) or set(bodies) != set(participants):
            raise ValueError('Original surrounding actor identities differ')
        gap, bearing, acceleration_by_actor, time_to_conflict = {}, {}, {}, {}
        for actor_id in participants:
            other = _body(bodies[actor_id], actor_id)
            dx, dy = other[0] - ego[0], other[1] - ego[1]
            gap[actor_id] = hypot(dx, dy) - ego[2] - other[2]
            if gap[actor_id] <= 0:
                time_to_conflict[actor_id] = 0.0
            elif actor_id in prior_gaps:
                closing_speed = (prior_gaps[actor_id] - gap[actor_id]) / .05
                time_to_conflict[actor_id] = gap[actor_id] / closing_speed if closing_speed > 0 else None
            else:
                time_to_conflict[actor_id] = None
            prior_gaps[actor_id] = gap[actor_id]
            bearing[actor_id] = degrees(atan2(heading[0] * dy - heading[1] * dx,
                                                heading[0] * dx + heading[1] * dy))
            try:
                speed = float(bodies[actor_id]['speed_mps'])
            except (KeyError, TypeError, ValueError) as error:
                raise ValueError('Original surrounding speed missing') from error
            if not isfinite(speed) or speed < 0:
                raise ValueError('Original surrounding speed invalid')
            if actor_id in speeds:
                acceleration = (speed - speeds[actor_id]) / .05
                acceleration_by_actor[actor_id] = acceleration
            else:
                acceleration_by_actor[actor_id] = None
            speeds[actor_id] = speed
        observations.append({'frame': frame, 'time_s': time_s,
                             'ego_longitudinal_speed_mps': longitudinal,
                             'backing_observed': longitudinal < 0,
                             'surface_gaps_m': gap, 'relative_bearings_deg': bearing,
                             'sampled_time_to_conflict_s': time_to_conflict,
                             'participant_acceleration_mps2': acceleration_by_actor,
                             'contact_actor_ids': contact_ids})
    backing = [row for row in observations if row['backing_observed']]
    first, last = (backing[0]['frame'], backing[-1]['frame']) if backing else (None, None)
    if backing and len(backing) != last - first + 1:
        raise ValueError('Backing motion has an unreviewed interruption')
    window = [row for row in observations if first is not None and first <= row['frame'] <= last]
    return {'format': 'worker-backing-safety-observation',
            'sources': {'backing_motion.jsonl': motion_sha,
                        'backing_contacts.jsonl': contact_sha,
                        'backing_context.json': sha256(context_raw).hexdigest()},
            'backing_onset_frame': first, 'backing_end_frame': last,
            'minimum_surface_gap_during_backing_m': {
                actor_id: min((row['surface_gaps_m'][actor_id] for row in window),
                              default=None)
                for actor_id in participants},
            'minimum_sampled_time_to_conflict_during_backing_s': {
                actor_id: min((row['sampled_time_to_conflict_s'][actor_id]
                               for row in window if row['sampled_time_to_conflict_s'][actor_id] is not None),
                              default=None)
                for actor_id in participants},
            'contact_frames_during_backing': [row['frame'] for row in window
                                              if row['contact_actor_ids']],
            'minimum_sampled_surrounding_acceleration_during_backing_mps2': {
                actor_id: min((row['participant_acceleration_mps2'][actor_id]
                               for row in window if row['participant_acceleration_mps2'][actor_id] is not None),
                              default=None)
                for actor_id in participants},
            'participant_context': participants, 'observations': observations,
            'reasonable_safety_legal_judgment': None,
            'interference_legal_judgment': None}

"""CARLA-independent closed-loop reverse controller for a sourced corridor.

The requested target is a point behind the vehicle. Native readbacks, rather
than this command, determine whether the backing movement was realized.
"""

from math import atan2, hypot, isfinite, pi


def _angle(value):
    return (value + pi) % (2 * pi) - pi


def command(position_xy, heading_rad, signed_speed_mps, target_xy,
            target_reverse_speed_mps, *, stop_radius_m=0.35):
    values = [*position_xy, heading_rad, signed_speed_mps, *target_xy,
              target_reverse_speed_mps, stop_radius_m]
    if len(position_xy) != 2 or len(target_xy) != 2 or not all(isfinite(float(v)) for v in values):
        raise ValueError('Finite original position, heading, speed and target required')
    if target_reverse_speed_mps <= 0 or stop_radius_m <= 0:
        raise ValueError('Reverse target speed and stop radius must be positive')
    dx, dy = target_xy[0] - position_xy[0], target_xy[1] - position_xy[1]
    distance = hypot(dx, dy)
    if distance <= stop_radius_m:
        return {'reverse': True, 'throttle': 0.0, 'brake': 1.0, 'steer': 0.0,
                'target_reached': True}
    desired_heading = _angle(atan2(dy, dx) + pi)
    heading_error = _angle(desired_heading - heading_rad)
    # In reverse, yaw response has the opposite sign from steering input.
    steer = max(-0.8, min(0.8, -1.5 * heading_error))
    reverse_speed = max(0.0, -signed_speed_mps)
    error = target_reverse_speed_mps - reverse_speed
    throttle = max(0.0, min(0.55, 0.24 * error))
    brake = max(0.0, min(0.65, -0.3 * error))
    return {'reverse': True, 'throttle': throttle, 'brake': brake,
            'steer': steer, 'target_reached': False}

